1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"math/big"
7		"os"
8		"strings"
9	)
10	
11	type version struct {
12		major, minor, patch *big.Int
13		prerelease          bool
14	}
15	
16	func main() {
17		output, err := execute(os.Args[1:])
18		if err != nil {
19			fmt.Fprintln(os.Stderr, err)
20			os.Exit(2)
21		}
22		fmt.Fprintln(os.Stdout, output)
23	}
24	
25	func execute(args []string) (string, error) {
26		if len(args) != 2 {
27			return "", errors.New("usage: semverbump <version> <major|minor|patch|release>")
28		}
29	
30		v, err := parseVersion(args[0])
31		if err != nil {
32			return "", err
33		}
34	
35		switch args[1] {
36		case "major":
37			if v.prerelease && v.minor.Sign() == 0 && v.patch.Sign() == 0 {
38				return coreString(v), nil
39			}
40			return bumped(new(big.Int).Add(v.major, big.NewInt(1)), big.NewInt(0), big.NewInt(0)), nil
41		case "minor":
42			if v.prerelease && v.patch.Sign() == 0 {
43				return coreString(v), nil
44			}
45			return bumped(v.major, new(big.Int).Add(v.minor, big.NewInt(1)), big.NewInt(0)), nil
46		case "patch":
47			if v.prerelease {
48				return coreString(v), nil
49			}
50			return bumped(v.major, v.minor, new(big.Int).Add(v.patch, big.NewInt(1))), nil
51		case "release":
52			if !v.prerelease {
53				return "", errors.New("release requires a prerelease version")
54			}
55			return coreString(v), nil
56		default:
57			return "", fmt.Errorf("unknown bump kind %q", args[1])
58		}
59	}
60	
61	func bumped(major, minor, patch *big.Int) string {
62		return major.String() + "." + minor.String() + "." + patch.String()
63	}
64	
65	func coreString(v version) string {
66		return bumped(v.major, v.minor, v.patch)
67	}
68	
69	func parseVersion(input string) (version, error) {
70		var zero version
71		if strings.HasPrefix(input, "v") {
72			input = input[1:]
73		}
74		if input == "" {
75			return zero, errors.New("invalid version")
76		}
77	
78		parts := strings.Split(input, "+")
79		if len(parts) > 2 || parts[0] == "" {
80			return zero, errors.New("invalid version")
81		}
82		if len(parts) == 2 && !validIdentifiers(parts[1], false) {
83			return zero, errors.New("invalid version")
84		}
85	
86		coreAndPrerelease := strings.SplitN(parts[0], "-", 2)
87		core := strings.Split(coreAndPrerelease[0], ".")
88		if len(core) != 3 {
89			return zero, errors.New("invalid version")
90		}
91		major, ok := numericIdentifier(core[0])
92		if !ok {
93			return zero, errors.New("invalid version")
94		}
95		minor, ok := numericIdentifier(core[1])
96		if !ok {
97			return zero, errors.New("invalid version")
98		}
99		patch, ok := numericIdentifier(core[2])
100		if !ok {
101			return zero, errors.New("invalid version")
102		}
103	
104		prerelease := false
105		if len(coreAndPrerelease) == 2 {
106			prerelease = true
107			if !validIdentifiers(coreAndPrerelease[1], true) {
108				return zero, errors.New("invalid version")
109			}
110		}
111	
112		return version{major: major, minor: minor, patch: patch, prerelease: prerelease}, nil
113	}
114	
115	func numericIdentifier(input string) (*big.Int, bool) {
116		if input == "" || (len(input) > 1 && input[0] == '0') || !allDigits(input) {
117			return nil, false
118		}
119		n, ok := new(big.Int).SetString(input, 10)
120		return n, ok
121	}
122	
123	func validIdentifiers(input string, prerelease bool) bool {
124		if input == "" {
125			return false
126		}
127		for _, identifier := range strings.Split(input, ".") {
128			if identifier == "" {
129				return false
130			}
131			if !allSemverIdentifierChars(identifier) {
132				return false
133			}
134			if prerelease && len(identifier) > 1 && identifier[0] == '0' && allDigits(identifier) {
135				return false
136			}
137		}
138		return true
139	}
140	
141	func allDigits(input string) bool {
142		for i := 0; i < len(input); i++ {
143			if input[i] < '0' || input[i] > '9' {
144				return false
145			}
146		}
147		return true
148	}
149	
150	func allSemverIdentifierChars(input string) bool {
151		for i := 0; i < len(input); i++ {
152			c := input[i]
153			if (c < '0' || c > '9') && (c < 'A' || c > 'Z') && (c < 'a' || c > 'z') && c != '-' {
154				return false
155			}
156		}
157		return true
158	}
