5	func TestExecuteBumpsVersions(t *testing.T) {
6		tests := []struct {
7			name string
8			args []string
9			want string
10		}{
11			{name: "major", args: []string{"1.2.3", "major"}, want: "2.0.0"},
12			{name: "minor", args: []string{"10.20.30", "minor"}, want: "10.21.0"},
13			{name: "patch", args: []string{"0.0.0", "patch"}, want: "0.0.1"},
14			{name: "leading v and build metadata", args: []string{"v1.2.3+build.7", "patch"}, want: "1.2.4"},
15			{name: "prerelease patch finalizes", args: []string{"1.2.3-rc.1+meta", "patch"}, want: "1.2.3"},
16			{name: "prerelease minor advances", args: []string{"1.2.3-rc.1", "minor"}, want: "1.3.0"},
17			{name: "zero patch minor finalizes", args: []string{"1.2.0-beta.2", "minor"}, want: "1.2.0"},
18			{name: "zero lower components major finalizes", args: []string{"2.0.0-alpha.1", "major"}, want: "2.0.0"},
19			{name: "release", args: []string{"1.2.3-alpha", "release"}, want: "1.2.3"},
20		}
21	
22		for _, test := range tests {
23			t.Run(test.name, func(t *testing.T) {
24				got, err := execute(test.args)
25				if err != nil {
26					t.Fatalf("execute(%q): unexpected error: %v", test.args, err)
27				}
28				if got != test.want {
29					t.Fatalf("execute(%q) = %q, want %q", test.args, got, test.want)
30				}
31			})
32		}
33	}
