35	func TestExecuteRejectsInvalidInput(t *testing.T) {
36		tests := [][]string{
37			{"1.2.3", "release"},
38			{"1.2", "patch"},
39			{"01.2.3", "patch"},
40			{"1.2.3-", "patch"},
41			{"1.2.3-alpha..1", "patch"},
42			{"1.2.3-01", "patch"},
43			{"1.2.3+", "patch"},
44			{"1.2.3+meta..data", "patch"},
45			{"a.b.c", "patch"},
46			{"1.2.3", "bump"},
47			{"1.2.3"},
48			{},
49			{"1.2.3", "patch", "extra"},
50			{"-1.2.3", "patch"},
51		}
52	
53		for _, args := range tests {
54			t.Run(joinArgs(args), func(t *testing.T) {
55				if output, err := execute(args); err == nil {
56					t.Fatalf("execute(%q) = %q, nil error; want failure", args, output)
57				}
58			})
59		}
60	}
