62	func TestParseVersionAcceptsSemverIdentifiers(t *testing.T) {
63		for _, input := range []string{
64			"0.0.0",
65			"v1.2.3-rc.1+build.7",
66			"1.2.3-alpha-1+001",
67			"999999999999999999999999.0.0",
68		} {
69			if _, err := parseVersion(input); err != nil {
70				t.Errorf("parseVersion(%q): unexpected error: %v", input, err)
71			}
72		}
73	}
74	
75	func joinArgs(args []string) string {
76		if len(args) == 0 {
77			return "no arguments"
78		}
79		result := args[0]
80		for _, arg := range args[1:] {
81			result += " " + arg
82		}
83		return result
84	}
